<?php require_once 'includes/functions.php';$u=login_required('patient');if($_SERVER['REQUEST_METHOD']!=='POST')go('search.php');check_csrf();$did=(int)($_POST['donor_id']??0);$hospital=trim($_POST['hospital']??'');$details=trim($_POST['details']??'');$s=db()->prepare("SELECT u.user_id,dp.availability,dp.eligible FROM users u JOIN donor_profiles dp ON dp.user_id=u.user_id WHERE u.user_id=? AND u.role='donor'");$s->execute([$did]);$d=$s->fetch();if(!$d||$d['availability']!=='Available'||!$d['eligible']||!$hospital){flash('Donor unavailable or hospital is missing.','error');go('search.php');}$s=db()->prepare("INSERT INTO blood_requests(patient_id,donor_id,hospital,details) VALUES(?,?,?,?)");$s->execute([$u['user_id'],$did,$hospital,$details]);$id=(int)db()->lastInsertId();notice($did,'New blood request #'.$id.' from '.$u['name'],'request');flash('Blood request sent.');go('dashboard.php');?>